Here's a pytest test suite for your `slugify` function:

```python
# test_slugify.py
import pytest
from slugify import slugify


class TestSlugifyBasic:
    def test_lowercases_input(self):
        assert slugify("HELLO") == "hello"

    def test_replaces_single_space_with_hyphen(self):
        assert slugify("hello world") == "hello-world"

    def test_lowercases_and_replaces_together(self):
        assert slugify("Hello World") == "hello-world"

    def test_multi_word_phrase(self):
        assert slugify("The Quick Brown Fox") == "the-quick-brown-fox"


class TestSlugifyParams:
    @pytest.mark.parametrize(
        "raw, expected",
        [
            ("hello", "hello"),              # already slugged
            ("Hello World", "hello-world"),  # mixed case + space
            ("hello  world", "hello--world"),  # consecutive spaces -> double hyphen
            (" leading", "-leading"),        # leading space
            ("trailing ", "trailing-"),      # trailing space
            ("a b c", "a-b-c"),              # single chars
            ("", ""),                        # empty string
            ("   ", "---"),                  # only spaces
            ("123", "123"),                  # digits only
            ("Version 2 Release", "version-2-release"),  # digits mixed in
        ],
    )
    def test_expected_output(self, raw, expected):
        assert slugify(raw) == expected


class TestSlugifyEdgeCases:
    def test_empty_string(self):
        assert slugify("") == ""

    def test_single_character(self):
        assert slugify("A") == "a"

    def test_only_spaces(self):
        assert slugify("    ") == "----"

    def test_no_mutation_of_input(self):
        original = "Hello World"
        slugify(original)
        assert original == "Hello World"

    def test_tabs_and_newlines_are_not_replaced(self):
        # Only literal spaces are handled by this implementation
        assert slugify("hello\tworld") == "hello\tworld"
        assert slugify("hello\nworld") == "hello\nworld"

    def test_punctuation_is_preserved(self):
        # This implementation does NOT strip punctuation
        assert slugify("Hello, World!") == "hello,-world!"

    def test_unicode_is_lowercased(self):
        assert slugify("CAFÉ") == "café"


class TestSlugifyIdempotence:
    @pytest.mark.parametrize("raw", ["Hello World", "hello-world", "  spaced  ", "MiXeD"])
    def test_slugify_is_idempotent(self, raw):
        """Applying slugify twice should equal applying it once."""
        assert slugify(slugify(raw)) == slugify(raw)


class TestSlugifyTypeErrors:
    def test_rejects_non_string(self):
        with pytest.raises(AttributeError):
            slugify(123)

    def test_rejects_none(self):
        with pytest.raises(AttributeError):
            slugify(None)
```

A few notes on what these tests pin down:

- **The function's real contract is narrow.** It only lowercases and swaps the literal space character (`' '`) for `'-'`. It does *not* collapse repeated spaces, trim whitespace, or strip punctuation — so `"hello  world"` becomes `"hello--world"` and `"Hello, World!"` keeps its comma and bang. The parametrized cases lock in that actual behavior, and the two "documented quirk" tests (`tabs_and_newlines`, `punctuation_is_preserved`) make it explicit so a future refactor that changes this is caught deliberately rather than by surprise.
- **Non-string inputs raise `AttributeError`** (from `s.lower()` or `s.replace`), not a nice `TypeError`. I asserted the actual exception so the tests pass now; if you'd rather the function raise `TypeError` explicitly, change the tests to match the intended contract and update the function accordingly.
- **Idempotence** holds for this implementation and is a cheap, meaningful property to assert.

If you'd like, I can add a `conftest.py`, adapt these to a stricter slugify (trimming, collapsing spaces, stripping punctuation) if that's the behavior you actually intend, or swap in `hypothesis` for property-based testing.
